-- 시드 상품 729개의 이름에서 숫자·수량 표기를 걷어내고 설명을 장인이 만든 것처럼 다시 쓴다. 원본: scripts/demo-products/rename_products.py
-- 상품은 (현재 이름, 소분류 ID)로 찾고, 시드로 들어간 상품(thumbnail_url 이 저장소 docs 이미지)만 바꾼다. 큐레이션 33개(V17)는 건드리지 않는다.

CREATE TEMP TABLE demo_rename (old_title VARCHAR(200), subcategory_id BIGINT, new_title VARCHAR(200), new_description TEXT) ON COMMIT DROP;

UPDATE product p SET title = r.new_title, description = r.new_description, updated_at = NOW()
FROM demo_rename r
WHERE p.title = r.old_title AND p.subcategory_id = r.subcategory_id
  AND p.thumbnail_url LIKE '%/Jangingmall/backend/%/docs/%';
