INSERT INTO demo_rename VALUES
    ('김정옥 영남요 분청사기 다기세트', 1, '김정옥 영남요 분청사기 다기세트', '백토를 귀얄로 바르거나 담가 투박하고 자연스러운 결을 살린 분청 찻잔입니다. 유약 속 잔 균열은 쓸수록 자연스럽게 깊어집니다. 중성세제로 부드럽게 씻어 주세요.'),
    ('신정희요 수제 이도다완', 1, '신정희요 수제 이도다완', '손으로 빚은 형태 위에 유약을 얇게 입혀 구운 도자 찻잔입니다. 차 한 잔을 따르면 손안에 따뜻함이 고스란히 전해집니다. 유약 속 잔 균열은 쓸수록 자연스럽게 깊어집니다. 중성세제로 부드럽게 씻어 주세요.'),
    ('광주요 백자 청화 다기 3인 세트', 1, '광주요 백자 청화 다기 세트', '고운 백토를 물레에 올려 빚고 맑은 유약을 입혀 구운 찻잔입니다. 흡수가 적어 냄새가 배지 않고 씻기 편합니다.'),
    ('강진 청자 운학문 다기 세트', 1, '강진 청자 운학문 다기 세트', '은은한 비색 유약을 입혀 장작가마에서 구워 낸 청자 찻잔입니다. 구름과 학이 어우러진 상서로운 문양입니다. 유약 속 잔 균열은 쓸수록 자연스럽게 깊어집니다. 중성세제로 부드럽게 씻어 주세요.'),
    ('이종덕 옻칠 목다완 찻잔', 1, '이종덕 옻칠 목다완 찻잔', '나무 바탕에 천연 옻칠을 겹겹이 입혀 마무리한 찻잔입니다. 쓸수록 옻 특유의 깊은 윤기가 더해집니다.'),
    ('영남요 백자 3인 다기 찻잔', 1, '영남요 백자 다기 찻잔', '고운 백토를 물레에 올려 빚고 맑은 유약을 입혀 구운 찻잔입니다. 차 한 잔을 따르면 손안에 따뜻함이 고스란히 전해집니다. 마른 천으로 닦아 두면 맑은 흰빛이 오래갑니다.'),
    ('다도원 청자 상감 다관 및 잔세트', 1, '다도원 청자 상감 다관 및 잔세트', '은은한 비색 유약을 입혀 장작가마에서 구워 낸 청자 찻잔입니다. 급격한 온도 변화만 피하면 오래 쓸 수 있습니다.'),
    ('광주요 소리잔 찻잔 2인 세트', 1, '광주요 소리잔 찻잔 세트', '손으로 빚은 형태 위에 유약을 얇게 입혀 구운 도자 찻잔입니다. 차 한 잔을 따르면 손안에 따뜻함이 고스란히 전해집니다. 급격한 온도 변화만 피하면 오래 쓸 수 있습니다.'),
    ('신정희요 분청 찻잔 5인세트', 1, '신정희요 분청 찻잔 세트', '백토를 귀얄로 바르거나 담가 투박하고 자연스러운 결을 살린 분청 찻잔입니다. 급격한 온도 변화만 피하면 오래 쓸 수 있습니다.'),
    ('징광옹기 옹기 찻그릇 및 퇴수기', 1, '징광옹기 옹기 찻그릇 및 퇴수기', '흙을 한 켜씩 쌓아 두드려 모양을 만들고 불가마에서 구워 낸 옹기 징입니다. 찻자리의 분위기를 단정하게 잡아 줍니다. 처음 쓰기 전 쌀뜨물에 끓여 길들이면 더 오래 쓸 수 있습니다.'),
    ('김정옥 백자 수제 다관', 1, '김정옥 백자 수제 다관', '깨끗한 흰 바탕에 유약을 입혀 구운 백자 찻잔입니다. 흡수가 적어 냄새가 배지 않고 씻기 편합니다.'),
    ('강진 청자 상감 모란문 찻잔', 1, '강진 청자 상감 모란문 찻잔', '은은한 비색 유약을 입혀 장작가마에서 구워 낸 청자 찻잔입니다. 부귀를 뜻하는 모란 문양이 눈에 띕니다. 유약 속 잔 균열은 쓸수록 자연스럽게 깊어집니다. 중성세제로 부드럽게 씻어 주세요.'),
    ('광주요 미수 백자 2인 다기세트', 1, '광주요 미수 백자 다기세트', '백자 흙을 거르고 빚어 높은 온도의 가마에서 구워 낸 찻잔입니다. 흡수가 적어 냄새가 배지 않고 씻기 편합니다.'),
    ('신정희요 덤벙이 다완', 1, '신정희요 덤벙이 다완', '손으로 빚은 형태 위에 유약을 얇게 입혀 구운 도자 찻잔입니다. 차 한 잔을 따르면 손안에 따뜻함이 고스란히 전해집니다. 유약 속 잔 균열은 쓸수록 자연스럽게 깊어집니다. 중성세제로 부드럽게 씻어 주세요.'),
    ('이종덕 나주 옻칠 찻잔 받침 세트', 1, '이종덕 나주 옻칠 찻잔 받침 세트', '나무를 깎아 모양을 만들고 옻칠을 여러 번 덧발라 말린 찻잔입니다. 쓸수록 옻 특유의 깊은 윤기가 더해집니다.'),
    ('징광옹기 옹기 찻사발', 1, '징광옹기 옹기 찻사발', '흙을 한 켜씩 쌓아 두드려 모양을 만들고 불가마에서 구워 낸 옹기 징입니다. 찻자리의 분위기를 단정하게 잡아 줍니다. 숨구멍이 살아 있어 사용 후 충분히 말려 보관해 주세요.'),
    ('영남요 청화백자 찻잔', 1, '영남요 청화백자 찻잔', '깨끗한 흰 바탕에 유약을 입혀 구운 백자 찻잔입니다. 마른 천으로 닦아 두면 맑은 흰빛이 오래갑니다.'),
    ('전통 문양 현대식 다기 찻잔', 1, '청자빛 국화 다기 찻잔', '흙을 곱게 걸러 빚고 유약을 입혀 장작가마에서 구워 낸 찻잔입니다. 곧은 절개를 뜻하는 국화 문양이 돋보입니다. 급격한 온도 변화만 피하면 오래 쓸 수 있습니다.'),
    ('김수영 방짜유기 4인 옥식기 옥접시 세트', 2, '김수영 방짜유기 옥식기 옥접시 세트', '구리와 주석을 섞어 녹인 쇳물을 망치로 두드려 늘려 만든 그릇입니다. 색이 변하면 수세미에 소금을 묻혀 닦아 주세요.'),
    ('이형근 방짜유기 원형 찬접시 5종 세트', 2, '이형근 방짜유기 원형 찬접시 세트', '불과 망치질로 단단하게 다져 낸 놋쇠로 빚은 그릇입니다. 밥상 위에서 음식 색을 돋보이게 합니다. 쓸수록 은은한 윤이 나며, 식초 푼 물로 닦으면 본래 빛이 돌아옵니다.'),
    ('광주요 먹빛 옥형 접시 세트', 2, '광주요 먹빛 옥형 접시 세트', '흙을 곱게 걸러 빚고 유약을 입혀 장작가마에서 구워 낸 그릇입니다. 반찬부터 국까지 일상 식탁에 두루 어울립니다. 은은한 먹향이 퍼집니다.'),
    ('김정옥 영남요 분청 대접시', 2, '김정옥 영남요 분청 대접시', '백토를 귀얄로 바르거나 담가 투박하고 자연스러운 결을 살린 분청 그릇입니다. 반찬부터 국까지 일상 식탁에 두루 어울립니다. 유약 속 잔 균열은 쓸수록 자연스럽게 깊어집니다. 중성세제로 부드럽게 씻어 주세요.'),
    ('징광옹기 천연잿물 옹기 비빔밥 대접', 2, '징광옹기 천연잿물 옹기 비빔밥 대접', '황토와 잿물로 빚어 가마에서 구워 낸 징입니다. 처음 쓰기 전 쌀뜨물에 끓여 길들이면 더 오래 쓸 수 있습니다.'),
    ('허진규 옹기 숨쉬는 옹기 접시', 2, '허진규 옹기 숨쉬는 옹기 접시', '숨 쉬는 옹기 흙을 손으로 쌓아 올려 빚고 잿물을 입혀 구운 그릇입니다. 밥상 위에서 음식 색을 돋보이게 합니다. 처음 쓰기 전 쌀뜨물에 끓여 길들이면 더 오래 쓸 수 있습니다.'),
    ('김수영 방짜유기 무광 옥바리 밥그릇', 2, '김수영 방짜유기 무광 옥바리 밥그릇', '구리와 주석을 섞어 녹인 쇳물을 망치로 두드려 늘려 만든 그릇입니다. 색이 변하면 수세미에 소금을 묻혀 닦아 주세요.'),
    ('이형근 방짜유기 면기 2인 세트', 2, '이형근 방짜유기 면기 세트', '불과 망치질로 단단하게 다져 낸 놋쇠로 빚은 그릇입니다. 밥상 위에서 음식 색을 돋보이게 합니다. 색이 변하면 수세미에 소금을 묻혀 닦아 주세요.'),
    ('광주요 백자 양각 모란문 대접시', 2, '광주요 백자 양각 모란문 대접시', '고운 백토를 물레에 올려 빚고 맑은 유약을 입혀 구운 그릇입니다. 반찬부터 국까지 일상 식탁에 두루 어울립니다. 부귀를 뜻하는 모란 문양이 눈에 띕니다.'),
    ('남원목기 옻칠 목제 대접', 2, '남원목기 옻칠 목제 대접', '옻을 거르고 얇게 발라 말리기를 거듭해 깊은 윤기를 낸 그릇입니다. 반찬부터 국까지 일상 식탁에 두루 어울립니다. 쓸수록 옻 특유의 깊은 윤기가 더해집니다.'),
    ('강진 청자 음각 모란문 평접시', 2, '강진 청자 음각 모란문 평접시', '은은한 비색 유약을 입혀 장작가마에서 구워 낸 청자 그릇입니다. 반찬부터 국까지 일상 식탁에 두루 어울립니다. 부귀를 뜻하는 모란 문양이 눈에 띕니다.'),
    ('김정옥 백자 음각 연화문 파스타 접시', 2, '김정옥 백자 음각 연화문 파스타 접시', '고운 백토를 물레에 올려 빚고 맑은 유약을 입혀 구운 그릇입니다. 맑고 깨끗한 마음을 뜻하는 연꽃 문양입니다. 흡수가 적어 냄새가 배지 않고 씻기 편합니다.'),
    ('징광옹기 옹기 찬기 4종 세트', 2, '징광옹기 옹기 찬기 세트', '흙을 한 켜씩 쌓아 두드려 모양을 만들고 불가마에서 구워 낸 옹기 징입니다. 처음 쓰기 전 쌀뜨물에 끓여 길들이면 더 오래 쓸 수 있습니다.'),
    ('김수영 방짜유기 칠첩반상기 세트', 2, '김수영 방짜유기 칠첩반상기 세트', '불과 망치질로 단단하게 다져 낸 놋쇠로 빚은 그릇입니다. 밥상 위에서 음식 색을 돋보이게 합니다. 쓸수록 은은한 윤이 나며, 식초 푼 물로 닦으면 본래 빛이 돌아옵니다.'),
    ('이형근 방짜유기 원형 종지 3종', 2, '이형근 방짜유기 원형 종지', '달군 놋쇠를 불에서 꺼내 수백 번 두드려 모양을 잡은 방짜 그릇입니다. 쓸수록 은은한 윤이 나며, 식초 푼 물로 닦으면 본래 빛이 돌아옵니다.'),
    ('광주요 아뜰리에 먹빛 파스타볼', 2, '광주요 아뜰리에 먹빛 파스타볼', '물레에서 빚은 뒤 천천히 말려 가마에서 두 번 구워 낸 그릇입니다. 은은한 먹향이 퍼집니다. 유약 속 잔 균열은 쓸수록 자연스럽게 깊어집니다. 중성세제로 부드럽게 씻어 주세요.'),
    ('남원목기 물푸레나무 옻칠 공기 세트', 2, '남원목기 물푸레나무 옻칠 공기 세트', '나무 바탕에 천연 옻칠을 겹겹이 입혀 마무리한 그릇입니다. 쓸수록 옻 특유의 깊은 윤기가 더해집니다.'),
    ('허진규 옹기 둥근 나물 접시', 2, '허진규 옹기 둥근 나물 접시', '숨 쉬는 옹기 흙을 손으로 쌓아 올려 빚고 잿물을 입혀 구운 그릇입니다. 밥상 위에서 음식 색을 돋보이게 합니다. 숨구멍이 살아 있어 사용 후 충분히 말려 보관해 주세요.'),
    ('강진 청자 붓터치 원형 볼', 2, '강진 청자 붓터치 원형 볼', '은은한 비색 유약을 입혀 장작가마에서 구워 낸 청자 그릇입니다. 밥상 위에서 음식 색을 돋보이게 합니다. 붓끝이 부드럽게 모여 획이 고르게 나옵니다.'),
    ('김정옥 영남요 분청 고블렛 접시', 2, '김정옥 영남요 분청 고블렛 접시', '백토를 귀얄로 바르거나 담가 투박하고 자연스러운 결을 살린 분청 그릇입니다. 밥상 위에서 음식 색을 돋보이게 합니다. 급격한 온도 변화만 피하면 오래 쓸 수 있습니다.'),
    ('이형근 방짜유기 타원 사각 접시', 2, '이형근 방짜유기 타원 사각 접시', '달군 놋쇠를 불에서 꺼내 수백 번 두드려 모양을 잡은 방짜 그릇입니다. 색이 변하면 수세미에 소금을 묻혀 닦아 주세요.'),
    ('전통 문양 현대식 그릇 접시', 2, '잿빛 유약 둥근 접시', '물레에서 빚은 뒤 천천히 말려 가마에서 두 번 구워 낸 그릇입니다. 반찬부터 국까지 일상 식탁에 두루 어울립니다. 유약 속 잔 균열은 쓸수록 자연스럽게 깊어집니다. 중성세제로 부드럽게 씻어 주세요.'),
    ('김수영 방짜유기 무광 수저 2벌 세트', 3, '김수영 방짜유기 무광 수저 세트', '불과 망치질로 단단하게 다져 낸 놋쇠로 빚은 수저입니다. 쓸수록 은은한 윤이 나며, 식초 푼 물로 닦으면 본래 빛이 돌아옵니다.'),
    ('이형근 방짜유기 고급 옥수저 5벌 세트', 3, '이형근 방짜유기 고급 옥수저 세트', '달군 놋쇠를 불에서 꺼내 수백 번 두드려 모양을 잡은 방짜 수저입니다. 입에 닿는 느낌이 부드럽고 손에 쥐는 맛이 좋습니다. 쓸수록 은은한 윤이 나며, 식초 푼 물로 닦으면 본래 빛이 돌아옵니다.'),
